const WebSocket = require('ws');
const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const ROLES = { ADMIN: 'admin', EDITOR: 'editor', VIEWER: 'viewer' };
const PERMISSIONS = {
  [ROLES.ADMIN]: ['read', 'write', 'execute', 'template'],
  [ROLES.EDITOR]: ['read', 'write', 'template'],
  [ROLES.VIEWER]: ['read']
};

const sessions = new Map();
const templateCache = new Map();

function generateToken() {
  return crypto.randomBytes(32).toString('hex');
}

function authenticate(username, password) {
  const users = {
    'admin': { password: 'hashed_admin_pw', role: ROLES.ADMIN },
    'editor': { password: 'hashed_editor_pw', role: ROLES.EDITOR },
    'viewer': { password: 'hashed_viewer_pw', role: ROLES.VIEWER }
  };
  const user = users[username];
  if (user && user.password === password) {
    return { username, role: user.role };
  }
  return null;
}

function hasPermission(role, permission) {
  return PERMISSIONS[role] && PERMISSIONS[role].includes(permission);
}

function sanitizeTemplateName(name) {
  const basename = path.basename(name);
  if (!/^[a-zA-Z0-9_-]+\.html$/.test(basename)) {
    throw new Error('Invalid template name');
  }
  return basename;
}

function processTemplateDirectives(content, context) {
  const directivePattern = /<!--#([a-z]+)\s+([^"]+="[^"]*"(?:\s+[^"]+="[^"]*")*)\s*-->/g;
  let result = content;
  let match;

  while ((match = directivePattern.exec(content)) !== null) {
    const directive = match[1];
    const attrs = parseAttributes(match[2]);

    if (directive === 'echo') {
      const varName = attrs['var'];
      if (context.variables && context.variables[varName] !== undefined) {
        result = result.replace(match[0], escapeHtml(String(context.variables[varName])));
      } else {
        result = result.replace(match[0], '');
      }
    } else if (directive === 'include') {
      const virtualPath = attrs['virtual'];
      if (virtualPath && isAllowedInclude(virtualPath)) {
        const includePath = path.join(__dirname, 'templates', 'includes', virtualPath);
        try {
          const includeContent = fs.readFileSync(includePath, 'utf8');
          result = result.replace(match[0], includeContent);
        } catch (e) {
          result = result.replace(match[0], '<!-- include error -->');
        }
      } else {
        result = result.replace(match[0], '<!-- blocked -->');
      }
    } else if (directive === 'exec') {
      result = result.replace(match[0], '<!-- exec disabled -->');
    } else if (directive === 'set') {
      const varName = attrs['var'];
      const value = attrs['value'];
      if (varName && context.variables) {
        context.variables[varName] = value;
      }
      result = result.replace(match[0], '');
    }
  }
  return result;
}

function parseAttributes(attrString) {
  const attrs = {};
  const attrPattern = /([a-z]+)="([^"]*)"/g;
  let m;
  while ((m = attrPattern.exec(attrString)) !== null) {
    attrs[m[1]] = m[2];
  }
  return attrs;
}

function isAllowedInclude(virtualPath) {
  const normalized = path.normalize(virtualPath);
  return !normalized.startsWith('..') && !path.isAbsolute(normalized);
}

function escapeHtml(str) {
  return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#039;');
}

function renderTemplate(templateName, userVariables, role) {
  const safeName = sanitizeTemplateName(templateName);
  const templatePath = path.join(__dirname, 'templates', safeName);

  let content;
  if (templateCache.has(safeName)) {
    content = templateCache.get(safeName);
  } else {
    content = fs.readFileSync(templatePath, 'utf8');
    templateCache.set(safeName, content);
  }

  const context = {
    variables: { ...userVariables, role: role, timestamp: Date.now() }
  };

  return processTemplateDirectives(content, context);
}

function buildDynamicTemplate(sections, role) {
  let template = '<!DOCTYPE html><html><body>';
  for (const section of sections) {
    if (section.type === 'header') {
      template += `<h1>${escapeHtml(section.content)}</h1>`;
    } else if (section.type === 'paragraph') {
      template += `<p>${escapeHtml(section.content)}</p>`;
    } else if (section.type === 'include' && hasPermission(role, 'template')) {
      template += `<!--#include virtual="${section.path}" -->`;
    } else if (section.type === 'variable' && hasPermission(role, 'template')) {
      template += `<!--#echo var="${section.name}" -->`;
    }
  }
  template += '</body></html>';
  return template;
}

function processDynamicContent(sections, variables, role) {
  const rawTemplate = buildDynamicTemplate(sections, role);
  const context = { variables: { ...variables, role: role } };
  return processTemplateDirectives(rawTemplate, context);
}

const server = http.createServer();
const wss = new WebSocket.Server({ server });

wss.on('connection', (ws) => {
  let session = null;

  ws.on('message', (data) => {
    try {
      const msg = JSON.parse(data);

      if (msg.action === 'login') {
        const user = authenticate(msg.username, msg.password);
        if (user) {
          const token = generateToken();
          session = { token, ...user };
          sessions.set(token, session);
          ws.send(JSON.stringify({ status: 'ok', token, role: user.role }));
        } else {
          ws.send(JSON.stringify({ status: 'error', message: 'Auth failed' }));
        }
      } else if (msg.action === 'render') {
        if (!session) {
          ws.send(JSON.stringify({ status: 'error', message: 'Not authenticated' }));
          return;
        }
        if (!hasPermission(session.role, 'template')) {
          ws.send(JSON.stringify({ status: 'error', message: 'No permission' }));
          return;
        }
        const result = renderTemplate(msg.template, msg.variables || {}, session.role);
        ws.send(JSON.stringify({ status: 'ok', html: result }));
      } else if (msg.action === 'dynamic') {
        if (!session) {
          ws.send(JSON.stringify({ status: 'error', message: 'Not authenticated' }));
          return;
        }
        if (!hasPermission(session.role, 'read')) {
          ws.send(JSON.stringify({ status: 'error', message: 'No permission' }));
          return;
        }
        const result = processDynamicContent(
          msg.sections || [], msg.variables || {}, session.role
        );
        ws.send(JSON.stringify({ status: 'ok', html: result }));
      }
    } catch (e) {
      ws.send(JSON.stringify({ status: 'error', message: 'Internal error' }));
    }
  });
});

server.listen(8080);
